from collections import deque
def comps(g, c):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==c and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            n=(y+dy,x+dx)
                            if 0<=n[0]<h and 0<=n[1]<w and g[n[0]][n[1]]==c and n not in seen:
                                seen.add(n); q.append(n)
                out.append(cells)
    return out
